<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-2xl font-bold text-slate-900">Kelola Staff</h1><p class="mt-1 text-sm text-slate-500">Kelola akun staff Admin yang mengelola data pelanggan.</p></div><a href="<?= e(url('/staff/create')) ?>" class="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/15 hover:bg-primary-dark"><span class="text-lg">+</span> Tambah Staff</a></section>
<section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><div class="overflow-hidden rounded-xl border border-slate-100"><?php if ($staff): ?><div class="table-wrap"><table class="w-full min-w-[700px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">No</th><th class="px-5 py-3">Nama Lengkap</th><th class="px-5 py-3">Username</th><th class="px-5 py-3">Role</th><th class="px-5 py-3">Dibuat</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($staff as $i => $row): ?><tr class="hover:bg-slate-50/70"><td class="px-5 py-4 text-slate-500"><?= $i + 1 ?></td><td class="px-5 py-4"><div class="flex items-center gap-3"><div class="flex h-9 w-9 items-center justify-center rounded-full bg-blue-100 text-sm font-bold text-primary"><?= e(strtoupper(substr($row['nama_lengkap'], 0, 1))) ?></div><span class="font-semibold text-slate-800"><?= e($row['nama_lengkap']) ?></span></div></td><td class="px-5 py-4 font-mono text-xs text-slate-600"><?= e($row['username']) ?></td><td class="px-5 py-4"><span class="badge badge-disetujui"><?= e($row['role']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= e(formatTanggal($row['created_at'])) ?></td><td class="px-5 py-4 text-right"><form method="post" action="<?= e(url('/staff/' . $row['id_user'])) ?>" data-confirm="Hapus staff <?= e($row['nama_lengkap']) ?>? Tindakan ini tidak dapat dibatalkan."><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="font-semibold text-danger hover:underline">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada staff'; $emptyText='Tambahkan staff pertama untuk memulai.'; require root_path('app/Views/components/empty-state.php'); endif; ?></div></section>
